package com.starcase.archive;
import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;
/** Strictly scoped native HTTP bridge for a user-scanned, expiring LAN handoff. */
final class LanTransfer16 {
 static boolean validPackage(String text){try{org.json.JSONObject p=new org.json.JSONObject(text);return "starcase-archive".equals(p.optString("format"))&&p.optInt("packageVersion")==1;}catch(Exception e){return false;}}
 static String validate(String text) throws Exception {URI u=new URI(text.trim());String host=u.getHost();if(!"http".equals(u.getScheme())||host==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||u.getPort()!=17653||!u.getPath().matches("/a/[A-Za-z0-9_-]{24,64}/"))throw new Exception("这不是星匣电脑端的互通二维码");String[] octets=host.split("\\.");if(octets.length!=4)throw new Exception("互通仅支持同一Wi-Fi内的电脑地址");int[] parts=new int[4];for(int i=0;i<4;i++){if(!octets[i].matches("[0-9]{1,3}"))throw new Exception("网络地址无效");if(octets[i].length()>1&&octets[i].startsWith("0"))throw new Exception("网络地址格式无效");parts[i]=Integer.parseInt(octets[i]);if(parts[i]>255)throw new Exception("网络地址无效");}boolean local=parts[0]==10||parts[0]==172&&parts[1]>=16&&parts[1]<=31||parts[0]==192&&parts[1]==168;if(!local)throw new Exception("请使用电脑在同一Wi-Fi下显示的二维码");return u.toASCIIString();}
 static String request(String address,String operation,String body) throws Exception {String base=validate(address);if(!"download".equals(operation)&&!"upload".equals(operation))throw new Exception("不支持的互通操作");HttpURLConnection connection=(HttpURLConnection)new URL(base+operation).openConnection();connection.setConnectTimeout(6000);connection.setReadTimeout(20000);connection.setInstanceFollowRedirects(false);connection.setRequestProperty("Accept","text/plain");try{if("upload".equals(operation)){if(body==null||body.length()>34*1024*1024||!validPackage(body))throw new Exception("互通数据无效或过大");byte[] bytes=body.getBytes(StandardCharsets.UTF_8);connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setFixedLengthStreamingMode(bytes.length);connection.setRequestProperty("Content-Type","text/plain; charset=utf-8");try(OutputStream out=connection.getOutputStream()){out.write(bytes);}}int status=connection.getResponseCode();if(status!=200)throw new Exception(status==404?"二维码已结束或过期，请在电脑重新开启互通":"电脑未接受本次传送，请检查电脑端是否有待接收数据");try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] chunk=new byte[32768];for(int n;(n=in.read(chunk))!=-1;){if(out.size()+n>34*1024*1024)throw new Exception("互通数据过大");out.write(chunk,0,n);}String text=new String(out.toByteArray(),StandardCharsets.UTF_8);if("download".equals(operation)&&!validPackage(text))throw new Exception("电脑返回的数据格式无效");return text;}}finally{connection.disconnect();}}
}
